import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.ktMMbWgA.js";const v=JSON.parse('{"title":"第 23 讲 · Embedding 与向量检索 — AI 的记忆系统 · 参考","description":"","frontmatter":{"title":"第 23 讲 · Embedding 与向量检索 — AI 的记忆系统 · 参考","act":5,"kind":"refs","prev":{"text":"L22 · 上下文工程","link":"/lectures/L22-context-engineering/references"},"next":{"text":"L24 · RAG","link":"/lectures/L24-rag/references"}},"headers":[],"relativePath":"lectures/L23-embedding-retrieval/references.md","filePath":"lectures/L23-embedding-retrieval/references.md","lastUpdated":null}'),i={name:"lectures/L23-embedding-retrieval/references.md"};function t(n,s,d,c,f,p){return e(),r("div",null,[...s[0]||(s[0]=[l('<h1 id="l23-references-embedding-与向量检索-—-ai-的记忆系统" tabindex="-1">L23 References: Embedding 与向量检索 — AI 的记忆系统 <a class="header-anchor" href="#l23-references-embedding-与向量检索-—-ai-的记忆系统" aria-label="Permalink to &quot;L23 References: Embedding 与向量检索 — AI 的记忆系统&quot;">​</a></h1><blockquote><p><strong>Lecture</strong>: Embedding 与向量检索 — AI 的记忆系统 <strong>Course</strong>: Intelligence, Computed — From First Principles to Production AI Systems</p></blockquote><blockquote><p><strong>Last Verified</strong>: 2026-05-04 (links and citations checked; replace this when re-verifying)</p></blockquote><hr><section class="ref-card"><h2 class="ref-card-title" id="学术论文">1. 学术论文</h2><h3 class="ref-group" id="学术论文--sentence-embedding-里程碑">Sentence Embedding 里程碑</h3><ol class="ref-list"><li class="ref-item" id="ref-P1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P1</span><a class="ref-title" href="https://arxiv.org/abs/1908.10084" target="_blank" rel="noopener">Sentence-BERT: Sentence Embeddings using Siamese BERT-Networks</a></div><div class="ref-meta">Reimers, N. &amp; Gurevych, I. · 2019 · <em>EMNLP 2019</em></div><p class="ref-desc"><strong>Sentence Transformers 原论文。</strong> 提出 Bi-Encoder 架构，把 BERT 变成句子级 Embedding 模型。讲稿 [07:00–10:00] 的核心参考。</p></div></li><li class="ref-item" id="ref-P2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P2</span><a class="ref-title" href="https://arxiv.org/abs/2212.03533" target="_blank" rel="noopener">Text Embeddings by Weakly-Supervised Contrastive Pre-training (E5)</a></div><div class="ref-meta">Wang, L., Yang, N., Huang, X. et al. · 2024 · <em>ACL 2024</em></div><p class="ref-desc"><strong>E5 原论文。</strong> 用弱监督对比预训练大幅提升 Embedding 质量。指令式 Embedding 的代表作。MTEB 排行榜长期领先。</p></div></li><li class="ref-item" id="ref-P3"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P3</span><a class="ref-title" href="https://arxiv.org/abs/2309.07597" target="_blank" rel="noopener">C-Pack: Packaged Resources To Advance General Chinese Embedding (BGE)</a></div><div class="ref-meta">Xiao, S., Liu, Z., Zhang, P. &amp; Muennighoff, N. · 2024 · <em>SIGIR 2024</em></div><p class="ref-desc"><strong>BGE 原论文。</strong> 中英双语 Embedding 模型。中文场景首选。讲稿 [10:00–12:00] 推荐的中文模型。</p></div></li></ol><h3 class="ref-group" id="学术论文--ann-算法核心论文">ANN 算法核心论文</h3><ol class="ref-list"><li class="ref-item" id="ref-P4"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P4</span><a class="ref-title" href="https://arxiv.org/abs/1603.09320" target="_blank" rel="noopener">Efficient and Robust Approximate Nearest Neighbor Search Using HNSW Graphs</a></div><div class="ref-meta">Malkov, Y. &amp; Yashunin, D. · 2020 · <em>IEEE TPAMI</em>, 42(4)</div><p class="ref-desc"><strong>HNSW 原论文。</strong> 多层导航图结构的 ANN 算法。讲稿 [28:00–32:00] &quot;社交网络跳跃导航&quot;类比的理论来源。</p></div></li><li class="ref-item" id="ref-P5"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P5</span><a class="ref-title" href="https://hal.inria.fr/inria-00514462" target="_blank" rel="noopener">Product Quantization for Nearest Neighbor Search</a></div><div class="ref-meta">Jégou, H., Douze, M. &amp; Schmid, C. · 2011 · <em>IEEE TPAMI</em>, 33(1)</div><p class="ref-desc"><strong>PQ 原论文。</strong> 向量压缩量化方法。讲稿 [28:00–32:00] &quot;指纹代替照片&quot;类比的来源。FAISS 的核心算法之一。</p></div></li><li class="ref-item" id="ref-P6"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P6</span><a class="ref-title" href="https://arxiv.org/abs/1702.08734" target="_blank" rel="noopener">Billion-Scale Similarity Search with GPUs (FAISS)</a></div><div class="ref-meta">Johnson, J., Douze, M. &amp; Jégou, H. · 2021 · <em>IEEE TBD</em>, 7(2)</div><p class="ref-desc"><strong>FAISS 原论文。</strong> Meta AI 开源的向量搜索库。GPU 加速 + IVF-PQ 组合索引。工业界 ANN 的事实标准。</p></div></li></ol><h3 class="ref-group" id="学术论文--向量检索评测">向量检索评测</h3><ol class="ref-list"><li class="ref-item" id="ref-P7"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P7</span><a class="ref-title" href="https://arxiv.org/abs/2210.07316" target="_blank" rel="noopener">MTEB: Massive Text Embedding Benchmark</a></div><div class="ref-meta">Muennighoff, N. et al. · 2023 · <em>EACL 2023</em></div><p class="ref-desc"><strong>MTEB 原论文。</strong> Embedding 模型选型的标准 benchmark。讲稿 [10:00–12:00] 推荐的排行榜来源。</p></div></li><li class="ref-item" id="ref-P8"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P8</span><a class="ref-title" href="http://ann-benchmarks.com/" target="_blank" rel="noopener">ANN-Benchmarks: A Benchmarking Tool for Approximate Nearest Neighbor Algorithms</a></div><div class="ref-meta">Aumüller, M., Bernhardsson, E. &amp; Faithfull, A. · 2020 · <em>Information Systems</em></div><p class="ref-desc">ANN 算法的标准 benchmark。比较 HNSW/IVF/PQ/Annoy 等在不同数据集上的 Recall-QPS 曲线。讲稿 [32:00–36:00] 性能数字的来源。</p></div></li></ol><h3 class="ref-group" id="学术论文--embedding-前沿">Embedding 前沿</h3><ol class="ref-list"><li class="ref-item" id="ref-P9"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P9</span><a class="ref-title" href="https://arxiv.org/abs/2205.13147" target="_blank" rel="noopener">Matryoshka Representation Learning</a></div><div class="ref-meta">Kusupati, A. et al. · 2022 · <em>NeurIPS 2022</em></div><p class="ref-desc">套娃式 Embedding——一个模型输出多种维度的向量。OpenAI text-embedding-3 的灵感来源。</p></div></li><li class="ref-item" id="ref-P10"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P10</span><a class="ref-title" href="https://arxiv.org/abs/2401.00368" target="_blank" rel="noopener">Improving Text Embeddings with Large Language Models</a></div><div class="ref-meta">Wang, L. et al. · 2024 · <em>arxiv preprint</em></div><p class="ref-desc">用 LLM 生成合成训绀数据来训练 Embedding 模型。E5-Mistral 的方法论。</p></div></li><li class="ref-item" id="ref-P11"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P11</span><a class="ref-title" href="https://arxiv.org/abs/2402.03216" target="_blank" rel="noopener">BGE M3-Embedding: Multi-Lingual, Multi-Functionality, Multi-Granularity Text Embeddings</a></div><div class="ref-meta">Chen, J., Xiao, S., Zhang, P. et al. · 2024 · <em>arxiv preprint</em></div><p class="ref-desc"><strong>BGE-M3 原论文。</strong> 同一模型同时输出 Dense / Sparse / Multi-Vector 三种表示。2024 年 Hybrid Search 的首选模型。</p></div></li><li class="ref-item" id="ref-P12"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P12</span><a class="ref-title" href="https://arxiv.org/abs/2405.17428" target="_blank" rel="noopener">NV-Embed: Improved Techniques for Training LLMs as Generalist Embedding Models</a></div><div class="ref-meta">Lee, C., Roy, R., Xu, M. et al. (NVIDIA) · 2024 · <em>arxiv preprint</em></div><p class="ref-desc">NV-Embed — NVIDIA 2024 SOTA on MTEB。如何把解码器 LLM 调调改造成顶级 Embedding 模型。</p></div></li><li class="ref-item" id="ref-P13"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P13</span><a class="ref-title" href="https://arxiv.org/abs/2402.09906" target="_blank" rel="noopener">GritLM: Generative Representational Instruction Tuning</a></div><div class="ref-meta">Muennighoff, N. et al. · 2024 · <em>arxiv preprint</em></div><p class="ref-desc">同一个模型同时做生成与 Embedding——走向「统一 LLM」的重要一步。</p></div></li><li class="ref-item" id="ref-P14"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P14</span><a class="ref-title" href="https://arxiv.org/abs/2112.01488" target="_blank" rel="noopener">ColBERTv2: Effective and Efficient Retrieval via Lightweight Late Interaction</a></div><div class="ref-meta">Santhanam, K., Khattab, O., Saad-Falcon, J. et al. · 2022 · <em>NAACL 2022</em></div><p class="ref-desc">ColBERTv2——Late Interaction 架构的实用版本，压缩 + 量化 + 多向量检索。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="书籍">2. 书籍</h2><ol class="ref-list"><li class="ref-item" id="ref-B1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B1</span><span class="ref-title"><strong>Speech and Language Processing</strong> (Ch. 6: Vector Semantics and Embeddings)</span></div><div class="ref-meta">Jurafsky, D. &amp; Martin, J.H. · 2024 (3rd ed. draft) · —</div><p class="ref-desc">同 L16。§6.1–6.8 覆盖词向量基础。本讲呼应 L16 时的教材级参考。免费在线：<a href="https://web.stanford.edu/~jurafsky/slp3/" target="_blank" rel="noopener">web.stanford.edu/~jurafsky/slp3/</a>。</p></div></li><li class="ref-item" id="ref-B2"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B2</span><span class="ref-title"><strong>Introduction to Information Retrieval</strong> (Ch. 1, 6, 8)</span></div><div class="ref-meta">Manning, C.D., Raghavan, P. &amp; Schütze, H. · 2008 · Cambridge University Press</div><p class="ref-desc">信息检索经典教材。TF-IDF、向量空间模型、索引结构。理解关键词搜索的权威参考。免费在线：<a href="https://nlp.stanford.edu/IR-book/" target="_blank" rel="noopener">nlp.stanford.edu/IR-book/</a>。</p></div></li><li class="ref-item" id="ref-B3"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B3</span><span class="ref-title">Foundations of Vector Retrieval</span></div><div class="ref-meta">Bruch, S. · 2024 · Springer</div><p class="ref-desc"><strong>向量检索专著。</strong> 系统覆盖 ANN 算法（LSH/KD-tree/HNSW/IVF/PQ）。学术深入但可读。讲稿 [26:00–36:00] ANN 部分的推荐深入阅读。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="博客与文章">3. 博客与文章</h2><ol class="ref-list"><li class="ref-item" id="ref-A1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A1</span><a class="ref-title" href="https://jalammar.github.io/illustrated-word2vec/" target="_blank" rel="noopener">The Illustrated Word2Vec</a></div><div class="ref-meta">Alammar, J.</div><p class="ref-desc">L16 呼应参考。Word2Vec 图解。</p></div></li><li class="ref-item" id="ref-A2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A2</span><a class="ref-title" href="https://jalammar.github.io/" target="_blank" rel="noopener">Text Embeddings Visually Explained</a></div><div class="ref-meta">Alammar, J.</div><p class="ref-desc">Sentence Embedding 的图解教程。Bi-Encoder vs Cross-Encoder 的可视化。</p></div></li><li class="ref-item" id="ref-A3"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A3</span><a class="ref-title" href="https://vickiboykis.com/what_are_embeddings/" target="_blank" rel="noopener">What Are Embeddings?</a></div><div class="ref-meta">Vicki Boykis</div><p class="ref-desc"><strong>Embedding 全景长文。</strong> 从 Word2Vec 到 Sentence Transformers 到向量数据库。配有精美插图。强烈推荐课前阅读。</p></div></li><li class="ref-item" id="ref-A4"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A4</span><a class="ref-title" href="https://www.pinecone.io/learn/series/faiss/hnsw/" target="_blank" rel="noopener">HNSW — Hierarchical Navigable Small World (Pinecone 图解)</a></div><div class="ref-meta">Pinecone Learning</div><p class="ref-desc"><strong>HNSW 最佳图解。</strong> 多层图导航的逐步可视化。讲稿 [28:00–32:00] 的核心视觉参考。</p></div></li><li class="ref-item" id="ref-A5"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A5</span><a class="ref-title" href="https://www.pinecone.io/learn/series/faiss/product-quantization/" target="_blank" rel="noopener">Product Quantization (Pinecone 图解)</a></div><div class="ref-meta">Pinecone Learning</div><p class="ref-desc">PQ 的直觉图解。子空间分割 + 码本的可视化。</p></div></li><li class="ref-item" id="ref-A6"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A6</span><a class="ref-title" href="https://towardsdatascience.com/" target="_blank" rel="noopener">Not All Vector Databases Are Made Equal</a></div><div class="ref-meta">Dmitry Kan / Towards Data Science</div><p class="ref-desc">向量数据库选型对比文章。Milvus vs Qdrant vs Weaviate vs pgvector。</p></div></li><li class="ref-item" id="ref-A7"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A7</span><a class="ref-title" href="https://blog.langchain.dev/" target="_blank" rel="noopener">Choosing a Vector Database</a></div><div class="ref-meta">LangChain Blog</div><p class="ref-desc">从 RAG 应用视角选型向量数据库。实用建议。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="视频">4. 视频</h2><ol class="ref-list"><li class="ref-item" id="ref-V1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V1</span><a class="ref-title" href="https://www.youtube.com/watch?v=wjZofJX0v4M" target="_blank" rel="noopener"><strong>3Blue1Brown · Word embeddings</strong> (GPT series)</a></div><div class="ref-meta">3Blue1Brown / Grant Sanderson · ~25 min</div><p class="ref-desc">词嵌入的视觉解释。L06 呼应。</p></div></li><li class="ref-item" id="ref-V2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V2</span><a class="ref-title" href="https://www.youtube.com/@jamesbriggs" target="_blank" rel="noopener">James Briggs · Vector Search from Scratch</a></div><div class="ref-meta">James Briggs · ~30 min</div><p class="ref-desc">向量搜索从零构建教程。FAISS + Sentence Transformers 实战。与本讲 demo 高度对齐。</p></div></li><li class="ref-item" id="ref-V3"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V3</span><a class="ref-title" href="https://www.youtube.com/@Fireship" target="_blank" rel="noopener">Fireship · Vector Databases explained in 100 seconds</a></div><div class="ref-meta">Fireship · ~2 min</div><p class="ref-desc">向量数据库极速入门。适合课前预习。</p></div></li><li class="ref-item" id="ref-V4"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V4</span><a class="ref-title" href="https://www.youtube.com/@Milvusio" target="_blank" rel="noopener">HNSW explained (visual walkthrough)</a></div><div class="ref-meta">Zilliz / Milvus · ~15 min</div><p class="ref-desc">HNSW 算法的可视化讲解。多层图导航动画。讲稿 [28:00–32:00] 的视觉辅助。</p></div></li><li class="ref-item" id="ref-V5"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V5</span><a class="ref-title" href="https://www.youtube.com/@StanfordOnline" target="_blank" rel="noopener">Stanford CS25 · Retrieval-Augmented Generation</a></div><div class="ref-meta">Stanford / Various · ~60 min</div><p class="ref-desc">RAG 全景讲座。本讲 Embedding 部分 + L30 RAG 部分的学术参考。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="代码仓库-tutorials">5. 代码仓库 &amp; Tutorials</h2><ol class="ref-list"><li class="ref-item" id="ref-C1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C1</span><a class="ref-title" href="https://www.sbert.net/" target="_blank" rel="noopener">sentence-transformers</a></div><div class="ref-meta">UKPLab / Reimers</div><p class="ref-desc"><strong>demo 代码的直接依赖。</strong> Sentence Embedding 模型库。`SentenceTransformer(&#39;all-MiniLM-L6-v2&#39;)` 一行加载。</p></div></li><li class="ref-item" id="ref-C2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C2</span><a class="ref-title" href="https://docs.trychroma.com/" target="_blank" rel="noopener">Chroma</a></div><div class="ref-meta">Chroma</div><p class="ref-desc"><strong>demo 代码的直接依赖。</strong> 轻量级向量数据库。`pip install chromadb` 即用。</p></div></li><li class="ref-item" id="ref-C3"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C3</span><a class="ref-title" href="https://github.com/facebookresearch/faiss" target="_blank" rel="noopener">FAISS</a></div><div class="ref-meta">Meta AI</div><p class="ref-desc">工业级向量搜索库。IVF/PQ/HNSW 全部支持。ANN 消融实验的底层实现。</p></div></li><li class="ref-item" id="ref-C4"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C4</span><a class="ref-title" href="https://milvus.io/docs" target="_blank" rel="noopener">Milvus</a></div><div class="ref-meta">Zilliz</div><p class="ref-desc">分布式向量数据库。生产环境十亿级场景。</p></div></li><li class="ref-item" id="ref-C5"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C5</span><a class="ref-title" href="https://qdrant.tech/documentation/" target="_blank" rel="noopener">Qdrant</a></div><div class="ref-meta">Qdrant</div><p class="ref-desc">高性能向量数据库。Rust 实现。</p></div></li><li class="ref-item" id="ref-C6"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C6</span><a class="ref-title" href="https://github.com/pgvector/pgvector" target="_blank" rel="noopener">pgvector</a></div><div class="ref-meta">Andrew Kane</div><p class="ref-desc">PostgreSQL 向量扩展。最低迁移成本。</p></div></li><li class="ref-item" id="ref-C7"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C7</span><a class="ref-title" href="https://huggingface.co/spaces/mteb/leaderboard" target="_blank" rel="noopener">MTEB Leaderboard</a></div><div class="ref-meta">Hugging Face</div><p class="ref-desc">Embedding 模型排行榜。选型必看。</p></div></li><li class="ref-item" id="ref-C8"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C8</span><a class="ref-title" href="http://ann-benchmarks.com/" target="_blank" rel="noopener">ann-benchmarks</a></div><div class="ref-meta">Aumüller et al.</div><p class="ref-desc">ANN 算法 benchmark。Recall-QPS 曲线对比。</p></div></li><li class="ref-item" id="ref-C9"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C9</span><a class="ref-title" href="https://github.com/FlagOpen/FlagEmbedding" target="_blank" rel="noopener">BGE / FlagEmbedding</a></div><div class="ref-meta">BAAI</div><p class="ref-desc">BAAI 官方 Embedding 仓库——BGE / BGE-M3 / BGE-Reranker 一站式使用。中文场景首选。</p></div></li><li class="ref-item" id="ref-C10"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C10</span><a class="ref-title" href="https://docs.voyageai.com/" target="_blank" rel="noopener">Voyage AI</a></div><div class="ref-meta">Voyage AI</div><p class="ref-desc">商业级 Embedding API——voyage-3-large 在 2025 年 MTEB 上领先，项目需要高精度检索时首选。</p></div></li><li class="ref-item" id="ref-C11"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C11</span><a class="ref-title" href="https://docs.cohere.com/docs/embeddings" target="_blank" rel="noopener">Cohere Embed v4</a></div><div class="ref-meta">Cohere</div><p class="ref-desc">Cohere 2025 年发布的多语言 Embedding——原生支持多模态与 Matryoshka 维度。</p></div></li><li class="ref-item" id="ref-C12"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C12</span><a class="ref-title" href="https://platform.openai.com/docs/guides/embeddings" target="_blank" rel="noopener">OpenAI text-embedding-3</a></div><div class="ref-meta">OpenAI</div><p class="ref-desc">OpenAI 2024 年发布的 Embedding API——原生 Matryoshka 可裁剪维度、价格下降 5×。</p></div></li><li class="ref-item" id="ref-C13"><span class="ref-stars" data-stars="3" aria-label="评级 3 星">●●●<span class="ref-stars-empty">○○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C13</span><a class="ref-title" href="https://lancedb.com/" target="_blank" rel="noopener">LanceDB</a></div><div class="ref-meta">LanceDB Inc.</div><p class="ref-desc">嵌入式向量数据库——同时支持全文检索 + 向量检索 + 表格查询，生产问友好。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="互动工具">6. 互动工具</h2><ol class="ref-list"><li class="ref-item" id="ref-T1"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T1</span><a class="ref-title" href="https://projector.tensorflow.org/" target="_blank" rel="noopener">TensorFlow Embedding Projector</a></div><p class="ref-desc">L16 呼应。词向量 t-SNE/PCA/UMAP 交互探索。</p></div></li><li class="ref-item" id="ref-T2"><span class="ref-stars" data-stars="5" aria-label="评级 5 星">●●●●●<span class="ref-stars-empty"></span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T2</span><a class="ref-title" href="https://huggingface.co/spaces/mteb/leaderboard" target="_blank" rel="noopener">MTEB Leaderboard</a></div><p class="ref-desc">现场展示 Embedding 模型排行。选型参考。</p></div></li><li class="ref-item" id="ref-T3"><span class="ref-stars" data-stars="4" aria-label="评级 4 星">●●●●<span class="ref-stars-empty">○</span></span><div class="ref-body"><div class="ref-head"><span class="ref-id">T3</span><a class="ref-title" href="http://ann-benchmarks.com/" target="_blank" rel="noopener">ann-benchmarks</a></div><p class="ref-desc">ANN 算法性能对比交互图表。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="阅读建议">阅读建议</h2><ol class="ref-list"><li class="ref-item" id="ref-S7-1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">层次：</span><strong>最小阅读</strong></p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">推荐组合：</span>A3 (Vicki Boykis Embeddings) + A4 (Pinecone HNSW 图解) + V3 (Fireship 100 秒)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">适合人群：</span>时间有限的学生</p></div></li><li class="ref-item" id="ref-S7-2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">层次：</span><strong>标准阅读</strong></p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">推荐组合：</span>P1 (Sentence-BERT) + A3 + A4 + B1 Ch.6 (Jurafsky) + V2 (James Briggs)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">适合人群：</span>想理解原理的学生</p></div></li><li class="ref-item" id="ref-S7-3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-title"></span></div><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">层次：</span><strong>深入阅读</strong></p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">推荐组合：</span>P1 + P4 (HNSW) + P5 (PQ) + P6 (FAISS) + P7 (MTEB) + B3 (Bruch 向量检索专著) + A5 (PQ 图解)</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">适合人群：</span>想构建完整知识体系的学生</p></div></li></ol></section>',11)])])}const m=a(i,[["render",t]]);export{v as __pageData,m as default};
